/** Mermaid aborts the entire render when an image cannot be decoded. Historical
 * reports may reference a local image service that is no longer running. */
export async function prepareMermaidImages(diagram: string) {
    // Match the image node syntax generated by idaes-connectivity, preserving
    // the quoted label so fallback nodes keep the original unit names.
    const imageNode = /^(\s*)(\w+)@\{\s*img:\s*"([^"]+)",\s*label:\s*("(?:[^"\\]|\\.)*")[^\n]*\}/gm;
    const nodes = [...diagram.matchAll(imageNode)];
    const urls = [...new Set(nodes.map(node => node[3]))];
    const unavailable = new Set<string>();

    await Promise.all(urls.map(async url => {
        const loaded = await new Promise<boolean>(resolve => {
            const img = new Image();
            const finish = (success: boolean) => {
                window.clearTimeout(timer);
                img.onload = null;
                img.onerror = null;
                resolve(success);
            };
            const timer = window.setTimeout(() => finish(false), 3000);
            img.onload = () => finish(true);
            img.onerror = () => finish(false);
            img.src = url;
        });
        if (!loaded) unavailable.add(url);
    }));

    return {
        diagram: diagram.replace(imageNode, (node, indent, id, url, label) =>
            unavailable.has(url) ? `${indent}${id}[${label}]` : node),
        missingImages: unavailable.size > 0,
    };
}
